    10	// The pi-agent-core Agent pushes messages in-place (same array reference),
    11	// so Lit's @property({ type: Array }) never detects the change. We replace the
    12	// array reference on message_end/agent_end so message-list re-renders.
    13	//
    14	// Separately, Agent#finishRun() — which clears `state.isStreaming` — runs in
    15	// the `finally` block of `runWithLifecycle`, *after* `agent_end` listeners
    16	// fire. AgentInterface's own `agent_end` handler calls `requestUpdate()` while
    17	// `isStreaming` is still true, so the MessageEditor renders the Abort button
    18	// and never re-renders. We force a follow-up render once `waitForIdle()`
    19	// resolves (post-finishRun), at which point `isStreaming` is false and the
    20	// Send button comes back.
    21	export function subscribeAgentEvents(agent: Agent, panel: AgentPanelLike) {
    22	  return agent.subscribe((ev) => {
    23	    if (ev.type === "message_end" || ev.type === "agent_end" || ev.type === "message_update" || ev.type === "message_start") {
    24	      const msgs = agent.state.messages;
    25	      agent.state.messages = [...msgs];
    26	    }
    27	    if (ev.type === "agent_end") {
